// ============================================================================
// F3 GDPR DATA DELETION
// Cron diario 00:00 Lima (05:00 UTC):
// 1. Fetch leads con context_json.request_data_deletion=true + state=closed
// 2. Para cada uno: POST /gdpr-execute (delete PII cross-system, preserva audit)
// Resuelve Gap B — compliance critical.
// ============================================================================

const AUDIT_TOKEN = $env.AUDIT_INTERNAL_TOKEN;
const ERP_BASE = 'https://erp.livskin.site';

if (!AUDIT_TOKEN) return [{ json: { error: 'AUDIT_INTERNAL_TOKEN missing' } }];

// Fetch pending GDPR deletions
let candidates;
try {
  candidates = await this.helpers.httpRequest({
    method: 'GET',
    url: ERP_BASE + '/api/internal/wa-state/gdpr-pending',
    headers: { 'X-Internal-Token': AUDIT_TOKEN },
    json: true,
    timeout: 10000,
  });
} catch (e) {
  return [{ json: { error: 'fetch failed: ' + e.message } }];
}

const items = (candidates && candidates.items) || [];
if (items.length === 0) {
  return [{ json: { skipped: true, reason: 'no pending GDPR requests', checked_at: new Date().toISOString() } }];
}

const results = { processed: [], errors: [], total: items.length };

for (const row of items) {
  try {
    const res = await this.helpers.httpRequest({
      method: 'POST',
      url: ERP_BASE + '/api/internal/wa-state/gdpr-execute',
      headers: { 'X-Internal-Token': AUDIT_TOKEN, 'Content-Type': 'application/json' },
      body: { phone_lead: row.phone_lead },
      json: true,
      timeout: 30000,
    });
    results.processed.push({ phone_hash: res.phone_hash, deleted: res.deleted });
  } catch (e) {
    results.errors.push({ phone: row.phone_lead, error: e.message });
  }
}

return [{ json: { ok: true, results, ran_at: new Date().toISOString() } }];
